package com.adib.maintenance;
import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class NavigationTimeTest {
@Test public void wholeMinutesAndHours(){assertEquals("0 dəq",WorkTimerClient.timeLabel(0));assertEquals("25 dəq",WorkTimerClient.timeLabel(25.9));assertEquals("59 dəq",WorkTimerClient.timeLabel(59.99));assertEquals("1 saat 0 dəq",WorkTimerClient.timeLabel(60));assertEquals("1 saat 15 dəq",WorkTimerClient.timeLabel(75.7));assertEquals("2 saat 5 dəq",WorkTimerClient.timeLabel(125));assertEquals("0 dəq",WorkTimerClient.timeLabel(Double.NaN));assertEquals("0 dəq",WorkTimerClient.timeLabel(-1));}
@Test public void homeNavigationHasFiveItemsWithoutTimer()throws Exception{JSONObject old=AccountSession.user;AccountSession.user=new JSONObject().put("id","test").put("role","admin");try{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();Field s=MainActivity.class.getDeclaredField("screen");s.setAccessible(true);s.set(a,"home");Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);Field f=MainActivity.class.getDeclaredField("root");f.setAccessible(true);View root=(View)f.get(a);assertNull(root.findViewWithTag("home-nav:6"));assertEquals(5,((LinearLayout)root.findViewWithTag("home-navigation")).getChildCount());assertNotNull(root.findViewWithTag("home-nav:7"));}finally{AccountSession.user=old;}}
@Test public void calendarNavigationHasNoTimer(){TaskCalendarActivity a=Robolectric.buildActivity(TaskCalendarActivity.class).get();a.phone=new CalendarPhoneUi(a);a.phone.render();assertFalse(contains(a.root,"Taymer"));}boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),text))return true;}return false;}
}
